def build_b2():
    print(f"Total raw B2 words defined: {len(B2_RAW)}")
    assert len(B2_RAW) == 300, f"Expected 300 B2 words, got {len(B2_RAW)}"
    
    words_data = []
    seen = set()
    for idx, item in enumerate(B2_RAW, start=1):
        word, pos, phonetic, meaning_th, meaning_en, example, synonyms, antonyms = item
        w_lower = word.lower().strip()
        if w_lower in seen:
            raise ValueError(f"Duplicate word in B2: {w_lower}")
        seen.add(w_lower)
        
        words_data.append({
            "id": f"v_b2_{idx:03d}",
            "word": w_lower,
            "part_of_speech": pos,
            "cefr_level": "B2",
            "phonetic": phonetic,
            "meaning_th": meaning_th,
            "meaning_en": meaning_en,
            "example_sentence": example,
            "synonyms": json.dumps(synonyms, ensure_ascii=False),
            "antonyms": json.dumps(antonyms, ensure_ascii=False),
            "frequency_tier": 1
        })
    
    with open("c:/MaMan/database/cefr_dataset/b2_words.json", "w", encoding="utf-8") as f:
        json.dump(words_data, f, ensure_ascii=False, indent=2)
    print(f"Successfully generated 300 B2 words to b2_words.json!")
    return words_data

if __name__ == "__main__":
    build_b2()
